script:
// ProgressBar (ds-metrics §7, linear): 6pt capsule, el3 track, accentPrimary fill of value × width (value clamped to
// 0…1); the fill width animates with @motion.smooth. Primitives have no fractional sizes, so the bar takes a numeric
// `width` param (it shadows the common width prop; e.g. "width": "=env.screenWidth - 32").
param value: number
param width: number = 240
